interface SearchAlgorithm<T extends Comparable<? super T>> {
    SearchResult search(SearchRequest<T> request);
}

class BinarySearch {
    public static void main(String[] args) {
        SearchType searchType = args.length > 0 ? SearchType.from(args[0]) : SearchType.BINARY;
        SearchAlgorithm<Integer> searchAlgorithm = SearchAlgorithmFactory.create(searchType);
        Integer[] values = { 2, 3, 4, 10, 40 };
        Integer target = 10;
        SearchRequest<Integer> request = SearchRequest.<Integer>builder()
                .values(values)
                .target(target)
                .build();

        SearchResult result = searchAlgorithm.search(request);
        if (!result.isFound()) {
            System.out.println("Element is not present in array");
        } else {
            System.out.println("Element is present at index " + result.index());
        }
    }
}

final class SearchAlgorithmFactory {
    private SearchAlgorithmFactory() {
    }

    static <T extends Comparable<? super T>> SearchAlgorithm<T> create(SearchType searchType) {
        if (searchType == null) {
            throw new IllegalArgumentException("searchType must not be null");
        }

        switch (searchType) {
            case BINARY:
                return new BinarySearchService<>();
            case LINEAR:
                return new LinearSearchService<>();
            default:
                throw new IllegalArgumentException("Unsupported search type: " + searchType);
        }
    }

    static <T extends Comparable<? super T>> SearchAlgorithm<T> binarySearch() {
        return create(SearchType.BINARY);
    }
}

